def parse_report(raw):
    """يعيد (سطور القيود DataFrame، عدد القيود). السطر: دائن، مدين، وصف، ...، كود الحساب (10 أرقام)."""
    wb = _open_xlsx(raw)
    ws = wb.active
    out = []
    cur = None
    for r in ws.iter_rows(values_only=True):
        r = list(r)
        if not any(x is not None for x in r):
            continue
        d = next((x for x in r if isinstance(x, (dt.datetime, dt.date))), None)
        if r[0] == "A" and d is not None:
            strs = [x for x in r if isinstance(x, str)]
            ints = [x for x in r if isinstance(x, int)]
            cur = dict(date=pd.Timestamp(d), entry=ints[0] if ints else None,
                       jname=next((s for s in strs if s != "A" and not re.match(r"^[\d\-\. ]+$", s) and len(s) > 3 and not s.startswith("IV")), ""),
                       voucher=next((s for s in strs if re.match(r"^\d{12}$", s)), ""))
            continue
        if cur is None or not isinstance(r[0], (int, float)) or isinstance(r[0], bool):
            continue
        strs = [x for x in r[1:] if isinstance(x, str)]
        code = next((s for s in reversed(strs) if re.match(r"^\d{10}$", s)), None)
        if code is None:
            continue
        nums = [x for x in r[1:] if isinstance(x, (int, float)) and not isinstance(x, bool)]
        debit = float(nums[0]) if nums else 0.0
        rest = [s for s in strs if s != code]
        out.append(dict(cur, credit=float(r[0] or 0), debit=debit, code=code, rest=rest))
    df = pd.DataFrame(out)
    return df


def bank_effects(df):
    """الأثر النقدي لكل سطر مقابل في قيد يمس حساباً بنكياً."""
    if df is None or len(df) == 0:
        return pd.DataFrame(columns=LINE_COLS), {"entries": 0, "internal": 0.0, "bank_net": 0.0}
    df = df.copy()
    df["key"] = df["entry"].astype(str) + "|" + df["voucher"].astype(str) + "|" + df["date"].astype(str)
    isb = df["code"].str.startswith(BANK_PREFIX)
    keys = set(df.loc[isb, "key"])
    sub = df[df["key"].isin(keys)].copy()
    bank = sub[sub["code"].str.startswith(BANK_PREFIX)]
    internal = 0.0
    g = bank.groupby("key").agg(d=("debit", "sum"), c=("credit", "sum"))
    both = g[(g.d > 0) & (g.c > 0)]
    internal = float(np.minimum(both.d, both.c).sum())
    cn = sub[~sub["code"].str.startswith(BANK_PREFIX)].copy()
    cn["الأثر النقدي"] = cn["credit"] - cn["debit"]
    cn = cn[cn["الأثر النقدي"].abs() > 0.004]

    def _cc(rest):
        cands = [x for x in rest[1:] if x not in ADMIN_UNITS and ("عقد" in x or "موحد" in x or "مركز" in x or "قراء" in x)]
        return max(cands, key=len) if cands else ""
    cn["مركز التكلفة"] = cn["rest"].map(_cc)
    cn["العقد"] = cn["rest"].map(lambda r: contract_of(" ".join(r[1:])))
    cn["البيان"] = cn["rest"].map(lambda r: r[0] if r else "")
    cn["الحساب المقابل"] = cn["code"].map(lambda c: COA_NAMES.get(c, c))
    cn["الشهر"] = cn["date"].dt.strftime("%Y-%m")
    cn["التاريخ"] = cn["date"].dt.strftime("%Y-%m-%d")
    cn["القيد"] = cn["entry"].astype(str)
    cn["كود الحساب"] = cn["code"]
    res = cn[LINE_COLS].reset_index(drop=True)
    info = {"entries": int(len(keys)), "internal": internal, "bank_net": float((bank["debit"] - bank["credit"]).sum())}
    return res, info


