def _ref_maps(refs, kind):
    """مفتاح (تاريخ، مبلغ) ← جهة، ومفتاح (شهر، مبلغ) ← جهة إن كان فريداً."""
    R = refs[refs["النوع"] == kind]
    exact, monthly, cnt = {}, {}, {}
    for _, r in R.iterrows():
        a = round(abs(float(r["المبلغ"])), 2)
        exact.setdefault((r["التاريخ"], a), r["الجهة"])
        mk = (str(r["التاريخ"])[:7], a)
        cnt[mk] = cnt.get(mk, 0) + 1
        monthly[mk] = r["الجهة"]
    monthly = {k: v for k, v in monthly.items() if cnt[k] == 1}
    return exact, monthly


def _lookup(maps, date, amt):
    exact, monthly = maps
    a = round(abs(float(amt)), 2)
    return exact.get((date, a)) or monthly.get((str(date)[:7], a)) or ""


# ---------------- التصنيف ----------------
def classify(lines, acct_rules, desc_rules, vend_rules=None, vmaps=None, act_rules=None, actmap=None):
    items = []
    vends = []
    acts = []
    for _, r in lines.iterrows():
        code, name, desc = str(r["كود الحساب"]), str(r["الحساب المقابل"]), str(r["البيان"])
        item = None
        for fld, pat, tgt in acct_rules:
            pat = str(pat)
            hit = (fld == "كود" and code.startswith(pat)) or (fld == "اسم" and pat in name) or (fld == "بيان" and pat in desc)
            if hit:
                item = tgt
                break
        vend = ""
        if vmaps is not None and r["الأثر النقدي"] < 0:
            vend = _lookup(vmaps, str(r["التاريخ"]), r["الأثر النقدي"])
        vends.append(vend)
        act = _act_lookup(actmap, vend)
        acts.append(act)
        if item == "@بيان":
            item = None
            if act:
                for pat, tgt in (act_rules or []):
                    if str(pat) in act:
                        item = tgt
                        break
            if item is not None:
                items.append(item)
                continue
            for pat, tgt in desc_rules:
                if str(pat) in desc:
                    item = tgt
                    break
            if item is None and vend:
                for pat, tgt in (vend_rules or []):
                    if str(pat) in vend:
                        item = tgt
                        break
            if item is None:
                item = UNCLASS_OUT if r["الأثر النقدي"] < 0 else UNCLASS_IN
        if item is None:
            item = UNCLASS_OUT if r["الأثر النقدي"] < 0 else UNCLASS_IN
        # الحسابات التي تُصنَّف حسب الإشارة
        if item == "سداد التمويل والمرابحات" and r["الأثر النقدي"] > 0:
            item = "متحصلات التمويل والمرابحات"
        if item == "شراء أصول وسيارات ومعدات" and r["الأثر النقدي"] > 0:
            item = "متحصلات بيع أصول وسيارات"
        items.append(item)
    out = lines.copy()
    out["البند"] = items
    out["المورد"] = vends
    out["النشاط"] = acts
    out["المجموعة"] = out["البند"].map(lambda i: ITEM_GROUP.get(i, "ت-خارج"))
    return out


# ---------------- التخزين ----------------
def _load_lines():
    try:
        if os.path.exists(DATA_FILE):
            d = pd.read_csv(DATA_FILE, encoding="utf-8-sig", dtype={"كود الحساب": str, "القيد": str})
            for c in LINE_COLS:
                if c not in d.columns:
                    d[c] = ""
            return d[LINE_COLS].fillna("")
    except Exception:
        pass
    return pd.DataFrame(columns=LINE_COLS)


def _save_lines(d):
    try:
        d.to_csv(DATA_FILE, index=False, encoding="utf-8-sig")
    except Exception:
        pass


def _merge(saved, default, nkey=1):
    """قواعد محفوظة بإصدار أقدم: تُؤخذ الافتراضية الجديدة ثم تُضاف إليها القواعد التي أضافها المستخدم."""
    dk = {tuple(map(str, r[:nkey])) for r in default}
    return [list(r) for r in default] + [list(r) for r in saved if tuple(map(str, r[:nkey])) not in dk]


def _load_rules():
    try:
        if os.path.exists(RULES_FILE):
            j = json.load(open(RULES_FILE, encoding="utf-8"))
            a, d = j["acct"], j["desc"]
            if j.get("ver", 0) < RULES_VERSION:
                a, d = _merge(a, DEFAULT_ACCT_RULES, 2), _merge(d, DEFAULT_DESC_RULES, 1)
            return pd.DataFrame(a, columns=["الحقل", "النمط", "البند"]), pd.DataFrame(d, columns=["النمط", "البند"])
    except Exception:
        pass
    return pd.DataFrame(DEFAULT_ACCT_RULES, columns=["الحقل", "النمط", "البند"]), pd.DataFrame(DEFAULT_DESC_RULES, columns=["النمط", "البند"])


def _load_vrules():
    try:
        if os.path.exists(RULES_FILE):
            j = json.load(open(RULES_FILE, encoding="utf-8"))
            if "vend" in j:
                v = j["vend"] if j.get("ver", 0) >= RULES_VERSION else _merge(j["vend"], DEFAULT_VENDOR_RULES, 1)
                return pd.DataFrame(v, columns=["النمط", "البند"])
    except Exception:
        pass
    return pd.DataFrame(DEFAULT_VENDOR_RULES, columns=["النمط", "البند"])


def _load_arules():
    try:
        if os.path.exists(RULES_FILE):
            j = json.load(open(RULES_FILE, encoding="utf-8"))
            if "act" in j:
                v = j["act"] if j.get("ver", 0) >= RULES_VERSION else _merge(j["act"], DEFAULT_ACT_RULES, 1)
                return pd.DataFrame(v, columns=["النمط", "البند"])
    except Exception:
        pass
    return pd.DataFrame(DEFAULT_ACT_RULES, columns=["النمط", "البند"])


def _save_rules(a, d, v=None):
    try:
        v = v if v is not None else st.session_state.get("cf_vrules", _load_vrules())
        json.dump({"ver": RULES_VERSION, "acct": a.values.tolist(), "desc": d.values.tolist(), "vend": v.values.tolist(), "open": float(st.session_state.get("cf_open", DEFAULT_OPEN)), "act": st.session_state.get("cf_arules", _load_arules()).values.tolist()}, open(RULES_FILE, "w", encoding="utf-8"), ensure_ascii=False)
    except Exception:
        pass


def _state():
    ss = st.session_state
    if "cf_lines" not in ss:
        ss["cf_lines"] = _load_lines()
    if "cf_rules" not in ss:
        ss["cf_rules"] = _load_rules()
    if "cf_refs" not in ss:
        ss["cf_refs"] = _load_refs()
    if "cf_open" not in ss:
        try:
            ss["cf_open"] = float(json.load(open(RULES_FILE, encoding="utf-8")).get("open", DEFAULT_OPEN)) if os.path.exists(RULES_FILE) else DEFAULT_OPEN
        except Exception:
            ss["cf_open"] = DEFAULT_OPEN
    if "cf_arules" not in ss:
        ss["cf_arules"] = _load_arules()
    if "cf_vrules" not in ss:
        ss["cf_vrules"] = _load_vrules()
    if "cf_info" not in ss:
        ss["cf_info"] = {}
    return ss["cf_lines"], ss["cf_rules"]


def classified():
    lines, (ar, dr) = _state()
    if len(lines) == 0:
        return lines.assign(البند=[], المجموعة=[])
    L = lines.copy()
    L["الأثر النقدي"] = pd.to_numeric(L["الأثر النقدي"], errors="coerce").fillna(0.0)
    refs = st.session_state.get("cf_refs", pd.DataFrame(columns=REF_COLS))
    vr = st.session_state.get("cf_vrules", pd.DataFrame(DEFAULT_VENDOR_RULES, columns=["النمط", "البند"]))
    vm = _ref_maps(refs, "مورد") if len(refs[refs["النوع"] == "مورد"]) else None
    ar_ = st.session_state.get("cf_arules", pd.DataFrame(DEFAULT_ACT_RULES, columns=["النمط", "البند"]))
    actmap = {_nm(a): b for a, b in refs[refs["النوع"] == "نشاط"][["الجهة", "البيان"]].values}
    C = classify(L, ar.values.tolist(), dr.values.tolist(), vr.values.tolist(), vm, ar_.values.tolist(), actmap)
    C["العميل"] = ""
    if len(refs[refs["النوع"] == "عميل"]):
        cm = _ref_maps(refs, "عميل")
        isc = C["البند"].isin(["تحصيلات من العملاء", UNCLASS_IN, "متحصلات تشغيلية أخرى"]) & (C["الأثر النقدي"] > 0)
        inv = {str(b).split(".")[0]: a for a, b in refs[refs["النوع"] == "فاتورة"][["الجهة", "البيان"]].values}

        def _cust(r):
            c = _lookup(cm, str(r["التاريخ"]), r["الأثر النقدي"])
            if c or not inv:
                return c
            hits = [inv[n] for n in re.findall(r"\d{4,6}", str(r["البيان"])) if n in inv]
            return max(set(hits), key=hits.count) if hits else ""
        cu = C.loc[isc].apply(_cust, axis=1)
        C.loc[isc, "العميل"] = cu
        hit = isc & (C["العميل"] != "")
        C.loc[hit, "العقد"] = C.loc[hit, "العميل"].map(contract_of)
    return C


def summary():
    """للفحوصات: صافي التدفق الكلي وغير المصنف."""
    C = classified()
    if len(C) == 0:
        return {"rows": 0, "net": 0.0, "unclassified": 0.0}
    un = C[C["البند"].isin([UNCLASS_IN, UNCLASS_OUT])]["الأثر النقدي"].abs().sum()
    return {"rows": int(len(C)), "net": float(C["الأثر النقدي"].sum()), "unclassified": float(un),
            "months": sorted(C["الشهر"].unique().tolist())}


