    # ---------- المصفوفة الشهرية ----------
    st.markdown('<div class="cf-title">مصفوفة التدفقات النقدية الشهرية</div>', unsafe_allow_html=True)
    piv = C.pivot_table(index="البند", columns="الشهر", values="الأثر النقدي", aggfunc="sum", fill_value=0.0)
    cols = list(sel)
    for m in cols:
        if m not in piv.columns:
            piv[m] = 0.0

    def vals(item):
        return [float(piv.loc[item, m]) if item in piv.index else 0.0 for m in cols]

    def block(title, group_keys, rows_out):
        its = [i for i, g in ITEMS if g in group_keys]
        its = [i for i in its if i in piv.index and abs(piv.loc[i, cols]).sum() > 0.004]
        tot = np.zeros(len(cols))
        if its:
            rows_out.append(("section", title, []))
            for i in its:
                v = vals(i)
                rows_out.append(("item", i, v + [sum(v)]))
                tot += np.array(v)
        return tot

    rows = []
    t_in = block("التدفقات التشغيلية: المتحصلات", {"ت-داخل"}, rows)
    t_out = block("التدفقات التشغيلية: المدفوعات", {"ت-خارج"}, rows)
    op = t_in + t_out
    rows.append(("subtotal", "صافي التدفقات التشغيلية", list(op) + [float(op.sum())]))
    t_inv = block("التدفقات الاستثمارية", {"س"}, rows)
    rows.append(("subtotal", "صافي التدفقات الاستثمارية", list(t_inv) + [float(t_inv.sum())]))
    t_fin = block("التدفقات التمويلية", {"م"}, rows)
    rows.append(("subtotal", "صافي التدفقات التمويلية", list(t_fin) + [float(t_fin.sum())]))
    t_cus = block("تحويلات العهد (إنفاق لاحق من الصناديق)", {"ع"}, rows)
    net = op + t_inv + t_fin + t_cus
